const file = $input.item.json;

return {
  fileName: file.name,
  filePath: file.path_display,
  fileId: file.id,
  uploadedAt: file.server_modified,
  fileSize: file.size,
  mimeType: file.name.endsWith('.pdf') ? 'application/pdf' : 'image/png',
  source: 'dropbox'
};

const fileName = $input.item.json.fileName.toLowerCase();

let documentType = 'unknown';
let extractionSchema = null;

if (fileName.includes('invoice') || fileName.includes('bill')) {
  documentType = 'invoice';
  extractionSchema = {
    vendor: 'string',
    invoiceNumber: 'string',
    invoiceDate: 'date',
    totalAmount: 'number',
    currency: 'string'
  };
} else if (fileName.includes('receipt')) {
  documentType = 'receipt';
  extractionSchema = {
    merchant: 'string',
    date: 'date',
    total: 'number'
  };
} else if (fileName.includes('contract')) {
  documentType = 'contract';
  extractionSchema = {
    parties: 'array',
    effectiveDate: 'date',
    contractValue: 'number'
  };
}

return {
  ...($input.item.json),
  documentType,
  extractionSchema
};

const ocrText = $input.item.json.fullText;
const documentType = $('Detect Document Type').item.json.documentType;

let extractionPrompt = '';

if (documentType === 'invoice') {
  extractionPrompt = `Extract data from this invoice.

**OCR Text:** ${ocrText}

Return JSON:
{
  "vendor": "Company name",
  "invoiceNumber": "Invoice #",
  "invoiceDate": "YYYY-MM-DD",
  "totalAmount": numeric value only,
  "currency": "USD/EUR/SEK",
  "confidence": "high/medium/low"
}`;
} else {
  extractionPrompt = `Extract key information from this document.

**OCR Text:** ${ocrText}

Return structured JSON.`;
}

return {
  extractionPrompt,
  ocrText,
  documentType
};

const extracted = $input.item.json.outputJson;
const documentType = $('Build Extraction Prompt').item.json.documentType;

const validationErrors = [];

if (documentType === 'invoice') {
  if (!extracted.vendor) validationErrors.push('Missing vendor');
  if (!extracted.invoiceNumber) validationErrors.push('Missing invoice number');
  if (!extracted.totalAmount) validationErrors.push('Missing total amount');
}

const isValid = validationErrors.length === 0;

return {
  ...extracted,
  isValid,
  validationErrors,
  validatedAt: new Date().toISOString()
};

const extracted = $input.item.json;
const fileMetadata = $('Extract File Metadata').item.json;

return {
  documentId: `${extracted.documentType || 'doc'}-${Date.now()}`,
  documentType: extracted.documentType,
  fileName: fileMetadata.fileName,
  vendor: extracted.vendor || extracted.merchant,
  invoiceNumber: extracted.invoiceNumber,
  invoiceDate: extracted.invoiceDate || extracted.date,
  totalAmount: extracted.totalAmount || extracted.total,
  currency: extracted.currency || 'SEK',
  status: 'processed',
  processedAt: new Date().toISOString()
};
